CustomField.formula:
/* Number (0) – Preview_Days_To_Accrue__c (inclusive) */
IF( ISBLANK(Payment_Due_Date__c), 0,
/* Compute previewStart = later of (Due + Grace + 1) and (Last Accrued + 1) */ IF( TODAY() < IF( ISBLANK(Last_Accrued_on__c), Payment_Due_Date__c + Grace_Period_Days__c + 1, IF( (Last_Accrued_on__c + 1) > (Payment_Due_Date__c + Grace_Period_Days__c + 1), Last_Accrued_on__c + 1, Payment_Due_Date__c + Grace_Period_Days__c + 1 ) ), 0, TODAY() - IF( ISBLANK(Last_Accrued_on__c), Payment_Due_Date__c + Grace_Period_Days__c + 1, IF( (Last_Accrued_on__c + 1) > (Payment_Due_Date__c + Grace_Period_Days__c + 1), Last_Accrued_on__c + 1, Payment_Due_Date__c + Grace_Period_Days__c + 1 ) ) + 1 /* inclusive of the start day */ ) )
